#include <bits/stdc++.h>
using namespace std;

long long recursiveFunction(long long n) {
    static unordered_map<long long, long long> memoMap;
    if (memoMap.count(n)) return memoMap[n];
    if (n <= 11) return min(n, 2 + (11 - n));
    long long base = 1, count = 1;
    while (base <= n) {
        base = base * 10 + 1;
        count++;
    }
    long long limit = base / 10;
    if (base > 2 * n) {
        long long times = n / limit;
        long long rem = n % limit;
        long long option1 = recursiveFunction(base - n) + count;
        long long option2 = times * (count - 1) + recursiveFunction(rem);
        return memoMap[n] = min(option1, option2);
    } else {
        long long times = n / limit;
        long long rem = n % limit;
        long long option1 = recursiveFunction(base - n) + count;
        long long option2 = times * (count - 1) + recursiveFunction(rem);
        return memoMap[n] = min(option1, option2);
    }
}

int main() {
    long long number;
    cin >> number;
    cout << recursiveFunction(number);
    return 0;
}
